<?php
declare(strict_types=1);
require_once __DIR__ . '/auth.php';
require_roles(['super_admin', 'finance_manager']);
require_once __DIR__ . '/config/database.php';
$pdo=database_connection();
$receipt=trim((string)($_GET['receipt']??''));
if($receipt===''||mb_strlen($receipt)>50){http_response_code(404);exit('رسید پیدا نشد.');}
$stmt=$pdo->prepare('SELECT p.receipt_number,p.amount,p.payment_method,p.received_at,p.notes,c.period_name,c.amount_due,c.discount_amount,y.name AS year_name,s.student_number,s.first_name,s.last_name,s.father_name,s.class_name,u.full_name AS received_by_full_name,u.username AS received_by_username FROM student_fee_payments p JOIN student_fee_charges c ON c.id=p.charge_id JOIN students s ON s.id=c.student_id JOIN school_years y ON y.id=c.school_year_id LEFT JOIN users u ON u.id=p.received_by WHERE p.receipt_number=? LIMIT 1');
$stmt->execute([$receipt]);$payment=$stmt->fetch();
if(!$payment){http_response_code(404);exit('رسید پیدا نشد.');}
function receipt_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
$methods=['cash'=>'نقدی','bank'=>'بانکی','other'=>'دیگر'];
?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>رسید پرداخت <?=receipt_h($payment['receipt_number'])?></title><link rel="stylesheet" href="assets/css/style.css"><style>
.receipt-page{max-width:760px;margin:30px auto;padding:20px}.receipt-card{background:#fff;border:1px solid #d9e1eb;border-radius:12px;padding:28px}.receipt-head{display:flex;justify-content:space-between;gap:20px;align-items:flex-start;border-bottom:2px solid #1f2937;padding-bottom:18px;margin-bottom:18px}.receipt-number{direction:ltr;text-align:left;font-weight:700}.receipt-table{width:100%;border-collapse:collapse;margin:20px 0}.receipt-table th,.receipt-table td{border-bottom:1px solid #e5e7eb;padding:12px;text-align:right}.receipt-table th{width:35%;background:#f8fafc}.receipt-total{font-size:20px;font-weight:800;text-align:left;padding:15px;background:#f1f5f9;border-radius:8px}.receipt-actions{display:flex;gap:10px;margin:18px 0;flex-wrap:wrap}.receipt-note{color:#64748b;font-size:13px;margin-top:20px}@media print{body{background:#fff!important}.admin-layout,.receipt-actions{display:none!important}.receipt-page{margin:0;padding:0;max-width:none}.receipt-card{border:0;border-radius:0;padding:0}}
</style></head><body class="profile-page"><div class="receipt-page"><div class="receipt-actions"><button class="button button-primary" onclick="window.print()">چاپ رسید</button><a class="button button-secondary" href="fee_payments.php">بازگشت به دریافت فیس</a></div><section class="receipt-card"><div class="receipt-head"><div><h1>رسید پرداخت فیس</h1><div><?=receipt_h($payment['year_name'])?> — <?=receipt_h($payment['period_name'])?></div></div><div class="receipt-number">Receipt: <?=receipt_h($payment['receipt_number'])?><br><span data-persian-display-date="<?=receipt_h(substr((string)$payment['received_at'],0,10))?>"></span></div></div><table class="receipt-table"><tbody><tr><th>شماره شاگرد</th><td><?=receipt_h($payment['student_number'])?></td></tr><tr><th>نام شاگرد</th><td><?=receipt_h($payment['first_name'].' '.$payment['last_name'])?></td></tr><tr><th>نام پدر</th><td><?=receipt_h($payment['father_name']?:'—')?></td></tr><tr><th>صنف</th><td><?=receipt_h($payment['class_name'])?></td></tr><tr><th>دوره</th><td><?=receipt_h($payment['period_name'])?></td></tr><tr><th>تاریخ و ساعت</th><td><?=receipt_h($payment['received_at'])?></td></tr><tr><th>روش پرداخت</th><td><?=receipt_h($methods[$payment['payment_method']]??'دیگر')?></td></tr><tr><th>دریافت‌کننده وجه</th><td><?=receipt_h(($payment['received_by_full_name']?:$payment['received_by_username'])?:'ثبت نشده (پرداخت قدیمی)')?></td></tr><tr><th>یادداشت</th><td><?=receipt_h($payment['notes']?:'—')?></td></tr></tbody></table><div class="receipt-total">مبلغ دریافت‌شده: <?=number_format((float)$payment['amount'],2)?></div><p class="receipt-note">این رسید تأیید دریافت مبلغ فوق برای دوره مشخص‌شده است. لطفاً آن را نزد خود نگه دارید.</p></section></div><link rel="stylesheet" href="assets/css/persian-calendar.css"><script src="assets/js/persian-calendar.js"></script></body></html>